import{_ as a,c as o,o as t,av as i}from"./chunks/framework.AOtbozFj.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"pages/changelog.md","filePath":"pages/changelog.md"}'),d={name:"pages/changelog.md"};function r(l,e,n,c,s,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><hr><h2 id="_0-8-10-2026-08-20" tabindex="-1"><code>0.8.10</code> - 2026-08-20 <a class="header-anchor" href="#_0-8-10-2026-08-20" aria-label="Permalink to &quot;`0.8.10` - 2026-08-20&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><a href="/simast/pages/update_project.html">Update project</a> (<code>PUT /projects/{uuid}</code>) and <a href="/simast/pages/update_activity.html">Update activity</a> (<code>PUT /projects/{uuid}/activities/{uuid}</code>) — update any subset of fields on an existing project or activity.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The update request schema now correctly shows every field as optional — only send the fields you want to change.</li><li>An empty or omitted <code>locations.departements</code> on Project creation is now reliably filled with all department codes.</li></ul><hr><h2 id="_0-8-9-2026-08-20" tabindex="-1"><code>0.8.9</code> - 2026-08-20 <a class="header-anchor" href="#_0-8-9-2026-08-20" aria-label="Permalink to &quot;`0.8.9` - 2026-08-20&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Project <code>locations.departements</code>/<code>communes</code>/<code>section_communales</code> are now validated against the real geographic referential — arbitrary or placeholder values (including <code>&quot;*&quot;</code>, which was never actually a supported wildcard) are rejected instead of silently accepted.</li><li>On Project creation, an empty or omitted <code>locations.departements</code> is now interpreted as &quot;all departments&quot; and automatically filled with the full list of real department codes.</li><li><code>callback_url</code> must use HTTPS for <code>PRODUCTION</code>/<code>STAGING</code> applications. <code>DEVELOPMENT</code>/<code>TESTING</code> still accept <code>http://</code> for local testing.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A <code>webhook_secret</code> rotation no longer invalidates a pending retro pull — the return URL signature stays valid regardless of when SIMAST performs the pull.</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>New <a href="/simast/pages/webhooks.html">Webhooks</a> page, documenting notification payloads (<code>demande.completed</code>/<code>demande.failed</code>) and signature verification.</li></ul><hr><h2 id="_0-8-8-2026-08-19" tabindex="-1"><code>0.8.8</code> - 2026-08-19 <a class="header-anchor" href="#_0-8-8-2026-08-19" aria-label="Permalink to &quot;`0.8.8` - 2026-08-19&quot;">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Webhook signature (<code>X-Webhook-Signature</code>) is now computed over <code>{timestamp}.{raw_body}</code> instead of the raw body alone, and includes a new <code>X-Webhook-Timestamp</code> header — reject deliveries older than ~5 minutes to protect against replay. <strong>Breaking</strong>: existing signature verification code must be updated to include the timestamp in the signed payload.</li><li><code>webhook_secret</code> can now be rotated from the Partner portal (per-Application &quot;Regenerate&quot; action). The previous secret stays valid for 24h after rotation so verification can be switched over without downtime.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><code>return_url</code> removed from the data request creation payload (<code>POST /activities/{uuid}/demandes</code>). Retro data is retrieved via your Application&#39;s <code>callback_url</code> — see <a href="/simast/pages/return_url.html">Return URL</a>.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><code>webhook_secret</code> is now shown in the API response exactly once (at Application creation and at each regeneration) instead of never being retrievable at all.</li></ul><hr><h2 id="_0-8-7-2026-08-11" tabindex="-1"><code>0.8.7</code> - 2026-08-11 <a class="header-anchor" href="#_0-8-7-2026-08-11" aria-label="Permalink to &quot;`0.8.7` - 2026-08-11&quot;">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Creating an activity or a data request now inherits the parent&#39;s locations whenever the field is omitted, empty, or contains an empty department list — previously only full omission worked, and the other forms failed validation</li><li><code>return_url</code> is no longer required when creating a data request</li><li><code>quantity</code> is now required only when creating a household extraction (DATA_LIST); it stays optional for search requests (vlookups), where it doesn&#39;t apply</li><li>The completion webhook (<code>demande.completed</code>) and the retro pull on <code>return_url</code> are now clearly documented as independent mechanisms — the webhook does not trigger an automatic pull</li><li>Webhook payloads now send <code>company_id</code>/<code>application_id</code> as UUIDs instead of internal database IDs</li><li>The <code>filters</code> format is now documented correctly (positional triplets instead of named objects), and <code>Locations</code> examples use real numeric codes instead of placeholder names</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Data requests could silently be created without a <code>quantity</code> or the geographic scope actually intended, due to a validation bug affecting all non-admin channels (Portal, Partner, Third-App)</li><li>Data extraction no longer fails entirely when a household has a member with no name — that member is skipped instead</li><li>Background jobs dispatched right after creating a request could occasionally fail with a &quot;not found&quot; error under load; they now correctly wait for the request to be fully saved first</li><li>API error responses no longer leak internal server file paths or stack traces</li><li>The retro pull now correctly reads the response envelope and the <code>beneficiary</code> field from the third-party&#39;s data</li><li>A failed household extraction (e.g. an internal SIMAST error) no longer leaves the request silently stuck as &quot;processing&quot; forever, indistinguishable from a legitimately empty result</li><li>An expired or invalid token now correctly returns <code>401 Unauthenticated.</code> (or <code>403</code> for permission errors) instead of a generic 500 error</li><li>The request creation response no longer includes a <code>password</code> field — it was a leftover from the partner portal login mechanism and was never meant for this channel</li></ul><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>return_url</code> is now documented as an accepted field on data request creation</li><li>New request status <code>FAILED</code>, with <code>last_error</code> and <code>failed_at</code> now available on the request detail, so a failed extraction can be diagnosed even if the webhook notification below is missed</li><li>New webhook event <code>demande.failed</code>, sent when a data request fails processing (mirrors <code>demande.completed</code>)</li></ul><hr><h2 id="_0-8-6-2026-03-25" tabindex="-1"><code>0.8.6</code> - 2026-03-25 <a class="header-anchor" href="#_0-8-6-2026-03-25" aria-label="Permalink to &quot;`0.8.6` - 2026-03-25&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>All documentation text translated from French to English</li><li>Auth response corrected: <code>token</code>/<code>expires_at</code> → <code>access_token</code>/<code>expires_in</code></li><li>Auth content-type corrected: <code>application/json</code> → <code>application/x-www-form-urlencoded</code></li><li>Location field corrected: <code>sections</code> → <code>section_communales</code> (create project &amp; activity)</li><li><code>code</code> field removed from project and activity creation (auto-generated by the server)</li></ul><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Interactive sandbox on all new endpoint pages</li><li>20+ missing endpoints documented: project/activity detail &amp; update, full sync endpoints, complaint CRUD, Orion search on all resources, <code>/revoke</code>, <code>/communes</code>, <code>/section-communales</code></li></ul><hr><h2 id="_0-8-5-2026-02-02" tabindex="-1"><code>0.8.5</code> - 2026-02-02 <a class="header-anchor" href="#_0-8-5-2026-02-02" aria-label="Permalink to &quot;`0.8.5` - 2026-02-02&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Interactive API Sandbox on all endpoint pages</li><li>New endpoint: <code>/me</code> - Get authenticated application info</li><li>New endpoint: <code>/introspect</code> - Validate and inspect access tokens</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed BASE_URL</li><li>Minor Improvement</li></ul><h2 id="_0-8-4-2026-01-12" tabindex="-1"><code>0.8.4</code> - 2026-01-12 <a class="header-anchor" href="#_0-8-4-2026-01-12" aria-label="Permalink to &quot;`0.8.4` - 2026-01-12&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Token validity verification endpoint.</li><li>Graphical portal to generate public keys and client secrets.</li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><p>Authenticate app with code</p></li><li><p>HTTP Method: <code>POST</code></p></li><li><p>Content Type: <code>application/json</code></p></li><li><p>URL: <code>[BASE_URL]/v1/third-app/auth</code></p></li></ul><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>String</td><td>true</td><td>The app code sended by mail</td></tr></tbody></table><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed sector in project creation</li><li>Fixed response when no data in request</li><li>Minor Improvement</li><li>Corrected grammatical errors in variable naming (e.g., <em>departments</em>).</li></ul><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>🔐 Security improvements.</li></ul><h2 id="_0-8-3-2026-01-05" tabindex="-1"><code>0.8.3</code> - 2026-01-05 <a class="header-anchor" href="#_0-8-3-2026-01-05" aria-label="Permalink to &quot;`0.8.3` - 2026-01-05&quot;">​</a></h2><h3 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h3><ul><li><p>Removed Authenticate app with code</p></li><li><p>HTTP Method: <code>POST</code></p></li><li><p>Content Type: <code>application/json</code></p></li><li><p>URL: <code>[BASE_URL]/v1/third-app/auth</code></p></li></ul><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>String</td><td>true</td><td>The app code sended by mail</td></tr></tbody></table><ul><li>Fixed sector in project creation</li><li>Fixed response when no data in request</li><li>Minor Improvement</li></ul><h2 id="_0-8-2-2025-12-18" tabindex="-1"><code>0.8.2</code> - 2025-12-18 <a class="header-anchor" href="#_0-8-2-2025-12-18" aria-label="Permalink to &quot;`0.8.2` - 2025-12-18&quot;">​</a></h2><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed sector in project creation</li><li>Fixed response when no data in request</li><li>Minor Improvement</li></ul><h2 id="_0-8-1-2025-11-29" tabindex="-1"><code>0.8.1</code> - 2025-11-29 <a class="header-anchor" href="#_0-8-1-2025-11-29" aria-label="Permalink to &quot;`0.8.1` - 2025-11-29&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Add option search request data endpoint</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Authentification attributes <ul><li>Use code Or Use Client Id and Secret.</li></ul></li><li>Improve pagination in data list</li></ul><h2 id="_0-8-2025-11-14" tabindex="-1"><code>0.8</code> - 2025-11-14 <a class="header-anchor" href="#_0-8-2025-11-14" aria-label="Permalink to &quot;`0.8` - 2025-11-14&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>API endpoints for Project Type</li><li>API endpoints for Activities Sector</li><li>API endpoints for Intervention Type</li><li>API endpoints for Beneficiary Type</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Authentification attributes <ul><li>instead of an unique code, Use code and secret.</li></ul></li></ul><h3 id="removed-2" tabindex="-1">Removed <a class="header-anchor" href="#removed-2" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>All timestamp data of API enpoints response</li></ul><hr><h2 id="_0-7-1-2025-10-01" tabindex="-1"><code>0.7.1</code> - 2025-10-01 <a class="header-anchor" href="#_0-7-1-2025-10-01" aria-label="Permalink to &quot;`0.7.1` - 2025-10-01&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Add Exemple of usage <ul><li>Search creation</li><li>Return Url in Data Request</li></ul></li><li>Add token expiration date</li></ul>',79)])])}const m=a(d,[["render",r]]);export{p as __pageData,m as default};
